         background:
           radial-gradient(circle at top, #dbeafe 0%, transparent 35%),
           linear-gradient(180deg, #eef4ff 0%, var(--bg) 100%);
         padding: 24px;
       }

       .shell {
         width: min(100%, 520px);
       }

       .card {
         background: var(--card);
         border: 1px solid rgba(217, 226, 236, 0.8);
         border-radius: var(--radius);
         box-shadow: var(--shadow);
         backdrop-filter: blur(14px);
         padding: 32px;
       }

       .eyebrow {
         margin: 0 0 10px;
         color: var(--accent);
         font-size: 0.85rem;
         font-weight: 700;
         letter-spacing: 0.08em;
         text-transform: uppercase;
       }

       h1 {
         margin: 0 0 12px;
         font-size: clamp(1.6rem, 3vw, 2.1rem);
         line-height: 1.15;
       }

       .description {
         margin: 0 0 28px;
         color: var(--muted);
         line-height: 1.6;
       }

       form {
         display: grid;
         gap: 20px;
       }

       .form-field {
         display: grid;
         gap: 10px;
         padding: 18px;
         border: 1px solid var(--border);
         border-radius: 16px;
         background: rgba(248, 251, 255, 0.9);
       }

       .checkbox-row {
         display: flex;
         align-items: flex-start;
         gap: 12px;
       }

       input[type="checkbox"] {
         width: 20px;
         height: 20px;
         margin-top: 2px;
         accent-color: var(--accent);
         flex: 0 0 auto;
       }

       label {
         font-weight: 600;
         line-height: 1.5;
       }

       .helper-text {
         margin: 0 0 0 32px;
         color: var(--muted);
         font-size: 0.95rem;
         line-height: 1.5;
       }

       .actions {
         display: flex;
         justify-content: flex-end;
       }

       button {
         border: 0;
         border-radius: 999px;
         padding: 0.95rem 1.35rem;
         background: linear-gradient(180deg, var(--accent) 0%, var(--accent-dark) 100%);
         color: white;
         font: inherit;
         font-weight: 700;
         cursor: pointer;
         box-shadow: 0 12px 24px rgba(37, 99, 235, 0.25);
       }

       button:focus-visible,
       input:focus-visible {
         outline: 3px solid rgba(37, 99, 235, 0.28);
         outline-offset: 2px;
       }

       @media (max-width: 480px) {
         .card {
           padding: 24px;
         }

         .actions {
           justify-content: stretch;
         }

         button {
           width: 100%;
         }
       }
     </style>
   </head>
   <body>
     <div id="root"></div>

     <script>
       const ConsentField = () => `
         <div class="form-field">
           <div class="checkbox-row">
             <input
               id="terms"
               name="terms"
               type="checkbox"
               required
               aria-describedby="terms-help"
             />
             <label for="terms">I agree to the Terms of Use</label>
           </div>
           <p class="helper-text" id="terms-help">You must agree before continuing.</p>
         </div>
       `;

       const App = () => `
         <main class="shell">
           <section class="card" aria-labelledby="page-title">
             <p class="eyebrow">Consent required</p>
             <h1 id="page-title">Please confirm your agreement</h1>
             <p class="description">
               Review and accept the Terms of Use to continue with your submission.
             </p>
             <form>
               ${ConsentField()}
               <div class="actions">
                 <button type="submit">Submit</button>
               </div>
             </form>
           </section>
         </main>
       `;

       document.getElementById("root").innerHTML = App();
     </script>
   </body>
 </html>

')
